// Adapted from organized-experiment-clinical-trial-tracker src/repositories/participantRepository.ts:15-44 @ c70bac4
// (mock-db replaced by an injected array; demo sessions from src/lib/auth/session.ts reduced to
// their accessScope so the repository runs standalone).
export const demoSessions = {
  'user-coordinator-site-101': { user: { id: 'user-coordinator-site-101', role: 'STUDY_COORDINATOR' }, accessScope: { canReadAllSites: false, siteIds: ['site-101'] } },
  'user-data-manager': { user: { id: 'user-data-manager', role: 'DATA_MANAGER' }, accessScope: { canReadAllSites: true, siteIds: [] } },
};

function canAccessSite(session, siteId) {
  return session.accessScope.canReadAllSites || session.accessScope.siteIds.includes(siteId);
}

export function createParticipantRepository(participants) {
  return {
    async list(session) {
      return participants.filter((participant) => canAccessSite(session, participant.siteId));
    },

    async findById(session, participantId) {
      const participant = participants.find((candidate) => candidate.id === participantId) ?? null;

      if (!participant) {
        return null;
      }

      if (!canAccessSite(session, participant.siteId)) {
        return null;
      }

      return participant;
    },
  };
}

export async function getParticipantDetail(repo, session, participantId) {
  const participant = await repo.findById(session, participantId);
  if (!participant) {
    throw new Error('Participant not found.');
  }
  return { participant };
}

